window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["lamborghini"]={html:"<div class=\"own-lamborghini\">\n  <!-- ── NAV (transparent, floating in darkness) ─────────────────────── -->\n  <header class=\"nav\" id=\"lamboNav\">\n    <div class=\"nav-in\">\n      <button class=\"menu-btn\" type=\"button\" aria-expanded=\"false\" aria-label=\"Open menu\" data-menu>\n        <span class=\"menu-lines\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\n        <span class=\"menu-label\">Menu</span>\n      </button>\n      <a class=\"brand\" href=\"#lamboTop\" aria-label=\"Northwind home\">\n        <span class=\"brand-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M12 2 3 7v10l9 5 9-5V7z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"M12 6.6 7.2 9.3v5.4L12 17.4l4.8-2.7V9.3z\" fill=\"currentColor\"/></svg>\n        </span>\n        <span class=\"brand-name\">Northwind</span>\n      </a>\n      <div class=\"nav-right\">\n        <a class=\"nav-icon\" href=\"#\" aria-label=\"Search\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n        </a>\n        <a class=\"nav-icon\" href=\"#\" aria-label=\"Saved\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 3h12v18l-6-4-6 4z\"/></svg>\n        </a>\n      </div>\n    </div>\n    <nav class=\"nav-drawer\" hidden data-drawer aria-label=\"Primary\">\n      <a href=\"#lamboTheatre\">The system</a>\n      <a href=\"#lamboModels\">Surfaces</a>\n      <a href=\"#lamboPerformance\">Performance</a>\n      <a href=\"#lamboPricing\">Plans</a>\n      <a href=\"#lamboNews\">News</a>\n    </nav>\n  </header>\n\n  <main id=\"lamboTop\">\n    <!-- ── HERO (full-viewport black stage) ──────────────────────────── -->\n    <section class=\"hero\">\n      <div class=\"hero-bg\" aria-hidden=\"true\">\n        <span class=\"hero-grid\"></span>\n        <span class=\"hero-glow\"></span>\n      </div>\n      <div class=\"hero-in\">\n        <p class=\"eyebrow\" data-reveal>The operations stage</p>\n        <h1 class=\"display-hero\" data-reveal>Every number.<br>Zero darkness.</h1>\n        <p class=\"hero-lead\" data-reveal>Northwind turns throughput, regions, and revenue into one governed ledger — built for operations that never slow down.</p>\n        <div class=\"hero-cta\" data-reveal>\n          <a class=\"btn btn-gold btn-large\" href=\"#lamboPricing\">Discover more</a>\n          <a class=\"btn btn-ghost\" href=\"#lamboTheatre\">Watch the tour</a>\n        </div>\n      </div>\n      <div class=\"hero-controls\" aria-hidden=\"true\">\n        <button class=\"hex-pause\" type=\"button\" tabindex=\"-1\" aria-label=\"Pause\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M9 7v10M15 7v10\"/></svg>\n        </button>\n      </div>\n      <span class=\"hero-progress\" aria-hidden=\"true\"><i></i></span>\n    </section>\n\n    <!-- ── THEATRE / FEATURE ROW ─────────────────────────────────────── -->\n    <section class=\"section\" id=\"lamboTheatre\">\n      <div class=\"wrap feature\">\n        <div class=\"feature-copy reveal\" data-reveal>\n          <p class=\"eyebrow\">The system</p>\n          <h2 class=\"display-2\">One ledger.<br>Six regions.</h2>\n          <p class=\"lead\">Logistics, revenue, and support share a single model — so a status change in one region updates the whole operation instantly, with the audit trail to prove it.</p>\n          <ul class=\"specs\">\n            <li><span class=\"spec-k\">Regions</span><span class=\"spec-v\">6 · one model</span></li>\n            <li><span class=\"spec-k\">Latency</span><span class=\"spec-v\">Real-time</span></li>\n            <li><span class=\"spec-k\">Audit</span><span class=\"spec-v\">Immutable</span></li>\n          </ul>\n          <a class=\"btn btn-gold\" href=\"#lamboModels\">Start configuration</a>\n        </div>\n        <div class=\"feature-visual reveal\" data-reveal aria-hidden=\"true\">\n          <div class=\"visual-head\"><span>Operations console</span><span class=\"tag-live\">Live</span></div>\n          <div class=\"visual-chart\">\n            <svg viewBox=\"0 0 360 150\" preserveAspectRatio=\"none\">\n              <g fill=\"#ffc000\" opacity=\".18\"><rect x=\"12\" y=\"72\" width=\"34\" height=\"78\"/><rect x=\"56\" y=\"48\" width=\"34\" height=\"102\"/><rect x=\"100\" y=\"88\" width=\"34\" height=\"62\"/><rect x=\"144\" y=\"36\" width=\"34\" height=\"114\"/><rect x=\"188\" y=\"62\" width=\"34\" height=\"88\"/><rect x=\"232\" y=\"26\" width=\"34\" height=\"124\"/><rect x=\"276\" y=\"54\" width=\"34\" height=\"96\"/><rect x=\"320\" y=\"40\" width=\"28\" height=\"110\"/></g>\n              <polyline points=\"29,60 73,40 117,78 161,30 205,52 249,18 293,44 334,32\" fill=\"none\" stroke=\"#ffc000\" stroke-width=\"2.5\"/>\n            </svg>\n          </div>\n          <ul class=\"visual-rows\" id=\"lamboRows\"></ul>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── SURFACES (cards on charcoal) ──────────────────────────────── -->\n    <section class=\"section\" id=\"lamboModels\">\n      <div class=\"wrap\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">Surfaces</p>\n          <h2 class=\"display-2\">Choose your command centre.</h2>\n        </div>\n        <div class=\"models\">\n          <article class=\"model reveal\" data-reveal>\n            <div class=\"model-photo photo-1\" aria-hidden=\"true\"><span class=\"hex\"></span></div>\n            <div class=\"model-body\">\n              <h3 class=\"model-name\">Console</h3>\n              <p>Live operations dashboards for the floor, refreshed the moment data moves.</p>\n              <a class=\"link\" href=\"#lamboPricing\">Read more</a>\n            </div>\n          </article>\n          <article class=\"model reveal\" data-reveal>\n            <div class=\"model-photo photo-2\" aria-hidden=\"true\"><span class=\"hex\"></span></div>\n            <div class=\"model-body\">\n              <h3 class=\"model-name\">Ledger</h3>\n              <p>The governed system of record behind every total, with lineage on every field.</p>\n              <a class=\"link\" href=\"#lamboPricing\">Read more</a>\n            </div>\n          </article>\n          <article class=\"model reveal\" data-reveal>\n            <div class=\"model-photo photo-3\" aria-hidden=\"true\"><span class=\"hex\"></span></div>\n            <div class=\"model-body\">\n              <h3 class=\"model-name\">Forecast</h3>\n              <p>Scenario planning and variance alerts that surface a slip before it hits the SLA.</p>\n              <a class=\"link\" href=\"#lamboPricing\">Read more</a>\n            </div>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── PERFORMANCE STATS (light band) ────────────────────────────── -->\n    <section class=\"section light\" id=\"lamboPerformance\">\n      <div class=\"wrap\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">Performance</p>\n          <h2 class=\"display-2\">Numbers that hold at speed.</h2>\n        </div>\n        <div class=\"stats\">\n          <div class=\"stat reveal\" data-reveal><b data-count=\"48.2\" data-decimals=\"1\">0</b><span>K shipments tracked</span></div>\n          <div class=\"stat reveal\" data-reveal><b data-count=\"99\" data-suffix=\"%\">0</b><span>on-time accuracy</span></div>\n          <div class=\"stat reveal\" data-reveal><b data-count=\"6\">0</b><span>regions in one view</span></div>\n          <div class=\"stat reveal\" data-reveal><b data-count=\"1\">0</b><span>day to close the month</span></div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── PRICING ───────────────────────────────────────────────────── -->\n    <section class=\"section\" id=\"lamboPricing\">\n      <div class=\"wrap\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">Plans</p>\n          <h2 class=\"display-2\">Configure your operation.</h2>\n        </div>\n        <div class=\"tiers\">\n          <article class=\"tier reveal\" data-reveal>\n            <h3 class=\"tier-name\">Starter</h3>\n            <p class=\"tier-note\">One team, one region.</p>\n            <p class=\"price\"><span>$0</span><small>/month</small></p>\n            <ul><li>3 seats</li><li>Core dashboards</li><li>Community support</li></ul>\n            <a class=\"btn btn-ghost btn-block\" href=\"#\">Start free</a>\n          </article>\n          <article class=\"tier tier-feat reveal\" data-reveal>\n            <span class=\"tier-flag\">Recommended</span>\n            <h3 class=\"tier-name\">Growth</h3>\n            <p class=\"tier-note\">Multi-region operations.</p>\n            <p class=\"price\"><span>$49</span><small>/seat/month</small></p>\n            <ul><li>Everything in Starter</li><li>Unlimited regions</li><li>Variance alerts</li><li>SSO + audit log</li></ul>\n            <a class=\"btn btn-gold btn-block\" href=\"#\">Start configuration</a>\n          </article>\n          <article class=\"tier reveal\" data-reveal>\n            <h3 class=\"tier-name\">Enterprise</h3>\n            <p class=\"tier-note\">Governed at scale.</p>\n            <p class=\"price\"><span>Custom</span></p>\n            <ul><li>Data residency</li><li>Dedicated CSM</li><li>On-site onboarding</li></ul>\n            <a class=\"btn btn-ghost btn-block\" href=\"#\">Contact us</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── NEWS ──────────────────────────────────────────────────────── -->\n    <section class=\"section\" id=\"lamboNews\">\n      <div class=\"wrap\">\n        <div class=\"sec-head reveal\" data-reveal>\n          <p class=\"eyebrow\">News</p>\n          <h2 class=\"display-2\">From the floor.</h2>\n        </div>\n        <div class=\"news\">\n          <article class=\"news-card reveal\" data-reveal>\n            <span class=\"news-date\">Oct 03</span>\n            <h3 class=\"news-title\">Forecast overlays land on every dashboard</h3>\n            <p>Variance bands now render on the console, so a projection sits beside the actual.</p>\n            <a class=\"link\" href=\"#\">Read more</a>\n          </article>\n          <article class=\"news-card reveal\" data-reveal>\n            <span class=\"news-date\">Sep 19</span>\n            <h3 class=\"news-title\">Region-level SLA rules and escalations</h3>\n            <p>Set thresholds per lane and page the right owner before a breach, not after.</p>\n            <a class=\"link\" href=\"#\">Read more</a>\n          </article>\n          <article class=\"news-card reveal\" data-reveal>\n            <span class=\"news-date\">Sep 05</span>\n            <h3 class=\"news-title\">Typed mutations for bulk operations</h3>\n            <p>Everything the console does is now available over a typed, auditable API.</p>\n            <a class=\"link\" href=\"#\">Read more</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── CTA BAND ──────────────────────────────────────────────────── -->\n    <section class=\"section tight\">\n      <div class=\"wrap\">\n        <div class=\"cta reveal\" data-reveal>\n          <h2 class=\"display-2\">Start the configuration.</h2>\n          <p>Set up Northwind in an afternoon and bring every region with you.</p>\n          <a class=\"btn btn-gold btn-large\" href=\"#\">Get started</a>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ──────────────────────────────────────────────────────── -->\n  <footer class=\"foot\">\n    <div class=\"wrap foot-in\">\n      <div class=\"foot-brand\">\n        <span class=\"brand-name\">Northwind</span>\n        <p>Operations analytics for teams that run on the numbers.</p>\n      </div>\n      <nav class=\"foot-cols\" aria-label=\"Footer\">\n        <div><h4>Product</h4><a href=\"#lamboTheatre\">The system</a><a href=\"#lamboModels\">Surfaces</a><a href=\"#lamboPricing\">Plans</a></div>\n        <div><h4>Company</h4><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n        <div><h4>Resources</h4><a href=\"#\">Docs</a><a href=\"#\">API</a><a href=\"#\">Status</a></div>\n        <div><h4>Legal</h4><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a></div>\n      </nav>\n    </div>\n    <div class=\"wrap foot-base\">\n      <span>© 2026 Northwind Analytics, Inc.</span>\n      <span>Sample content — showcase only</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ LAMBORGHINI — Northwind operations analytics in Lamborghini's nocturnal language ══\n   True black (#000000) canvas, uppercase LamboType display at tight line-heights,\n   Lamborghini Gold (#FFC000) reserved exclusively for primary CTAs, zero radius on\n   buttons and cards, hexagonal motifs, and the transparent ghost secondary. */\n\n.own-lamborghini {\n  --black: #000000;\n  --charcoal: #202020;\n  --dark-iron: #181818;\n  --gold: #ffc000;\n  --gold-dark: #917300;\n  --gold-text: #ffce3e;\n  --cyan: #29abe2;\n  --link: #3860be;\n  --white: #ffffff;\n  --smoke: #f5f5f5;\n  --graphite: #494949;\n  --ash: #8f8f8f;\n  --steel: #969696;\n  --iron: #555555;\n\n  --f-lambo: 'LamboType', Roboto, 'Helvetica Neue', Arial, sans-serif;\n  --f-fallback: 'Open Sans', Roboto, Arial, sans-serif;\n\n  --gut: clamp(20px, 3.5cqi, 40px);\n\n  position: relative;\n  background: var(--black);\n  color: var(--white);\n  font-family: var(--f-lambo);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-lamborghini *, .own-lamborghini *::before, .own-lamborghini *::after { box-sizing: border-box; }\n.own-lamborghini p { margin: 0; }\n.own-lamborghini a { color: inherit; text-decoration: none; }\n.own-lamborghini img, .own-lamborghini svg { display: block; }\n.own-lamborghini button { font: inherit; }\n.own-lamborghini :focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }\n\n.own-lamborghini .wrap { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 var(--gut); }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-lamborghini .eyebrow { font-size: 12px; font-weight: 500; letter-spacing: 0.96px; text-transform: uppercase; color: var(--gold-text); margin-bottom: 20px; }\n.own-lamborghini .display-hero { font-weight: 400; text-transform: uppercase; font-size: clamp(52px, 10cqi, 120px); line-height: 0.92; letter-spacing: 0; }\n.own-lamborghini .display-2 { font-weight: 400; text-transform: uppercase; font-size: clamp(34px, 5.4cqi, 80px); line-height: 1.13; letter-spacing: 0; max-width: 16ch; }\n.own-lamborghini .model-name { font-weight: 400; text-transform: uppercase; font-size: 27px; line-height: 1.37; letter-spacing: 0.3px; }\n.own-lamborghini .lead { color: var(--ash); margin-top: 20px; max-width: 52ch; font-size: 18px; line-height: 1.56; }\n\n/* ── buttons (zero radius) ───────────────────────────────────────────── */\n.own-lamborghini .btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  padding: 16px 24px; border: 1px solid transparent; border-radius: 0;\n  font-family: var(--f-lambo); font-size: 16px; font-weight: 400; line-height: 1.5;\n  cursor: pointer; white-space: nowrap;\n  transition: background-color .15s, color .15s, opacity .15s;\n}\n.own-lamborghini .btn-gold { background: var(--gold); color: var(--black); }\n.own-lamborghini .btn-gold:hover { background: var(--gold-dark); color: #fff; }\n.own-lamborghini .btn-gold.btn-large { padding: 24px; }\n.own-lamborghini .btn-ghost { background: transparent; color: var(--white); border-color: rgba(255,255,255,.5); font-size: 14.4px; font-weight: 300; letter-spacing: 0.2px; text-transform: uppercase; padding: 16px 22px; }\n.own-lamborghini .btn-ghost:hover { background: var(--cyan); color: #fff; border-color: transparent; }\n.own-lamborghini .btn-block { display: flex; width: 100%; }\n.own-lamborghini .light .btn-ghost { color: var(--black); border-color: rgba(0,0,0,.4); }\n.own-lamborghini .light .btn-ghost:hover { background: var(--cyan); color: #fff; }\n.own-lamborghini .link { display: inline-block; font-size: 14px; letter-spacing: 0.2px; text-transform: uppercase; color: var(--white); border-bottom: 1px solid var(--white); padding-bottom: 3px; transition: color .15s, border-color .15s; }\n.own-lamborghini .link:hover { color: var(--link); border-color: var(--link); }\n.own-lamborghini .light .link { color: var(--black); border-color: var(--black); }\n\n/* ── nav (transparent, floating) ─────────────────────────────────────── */\n.own-lamborghini .nav { position: sticky; top: 68px; z-index: 40; background: rgba(0,0,0,.55); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); transition: background-color .3s; }\n.own-lamborghini .nav.is-stuck { background: rgba(0,0,0,.86); }\n.own-lamborghini .nav-in { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 16px; height: 68px; padding: 0 var(--gut); }\n.own-lamborghini .brand { display: flex; align-items: center; gap: 10px; justify-self: center; }\n.own-lamborghini .brand-mark { display: grid; place-items: center; width: 30px; height: 30px; color: var(--white); }\n.own-lamborghini .brand-mark svg { width: 28px; height: 28px; }\n.own-lamborghini .brand-name { font-size: 16px; font-weight: 400; letter-spacing: 2px; text-transform: uppercase; }\n.own-lamborghini .menu-btn { display: flex; align-items: center; gap: 12px; background: none; border: 0; color: var(--white); cursor: pointer; justify-self: start; padding: 8px 0; }\n.own-lamborghini .menu-lines { display: grid; gap: 4px; width: 22px; }\n.own-lamborghini .menu-lines i { display: block; height: 2px; background: var(--white); transition: transform .2s, opacity .2s; }\n.own-lamborghini .menu-label { font-size: 14px; letter-spacing: 0.2px; text-transform: uppercase; }\n.own-lamborghini .nav-right { display: flex; align-items: center; gap: 8px; justify-self: end; }\n.own-lamborghini .nav-icon { display: grid; place-items: center; width: 44px; height: 44px; color: var(--white); }\n.own-lamborghini .nav-icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }\n.own-lamborghini .nav-drawer { display: none; }\n.own-lamborghini .nav-drawer:not([hidden]) { display: block; padding: 8px var(--gut) 20px; border-top: 1px solid #202020; }\n.own-lamborghini .nav-drawer a { display: block; padding: 16px 0; font-size: 20px; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid #202020; }\n.own-lamborghini .nav-drawer a:hover { color: var(--gold); }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-lamborghini .hero { position: relative; min-height: clamp(560px, 78vh, 760px); display: grid; align-items: center; overflow: clip; }\n.own-lamborghini .hero-bg { position: absolute; inset: 0; z-index: 0; }\n.own-lamborghini .hero-grid { position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px); background-size: 64px 64px; -webkit-mask-image: radial-gradient(120% 90% at 60% 40%, #000 20%, transparent 75%); mask-image: radial-gradient(120% 90% at 60% 40%, #000 20%, transparent 75%); }\n.own-lamborghini .hero-glow { position: absolute; left: 50%; top: 44%; transform: translate(-50%, -50%); width: min(900px, 96%); height: 560px; background: radial-gradient(closest-side, rgba(255,192,0,.14), rgba(255,192,0,.04) 55%, rgba(255,192,0,0) 78%); filter: blur(6px); }\n.own-lamborghini .hero-in { position: relative; z-index: 1; width: 100%; max-width: 1200px; margin: 0 auto; padding: clamp(64px, 10cqi, 120px) var(--gut); }\n.own-lamborghini .hero-lead { color: rgba(255,255,255,.78); margin: 26px 0 34px; max-width: 44ch; font-size: 18px; line-height: 1.56; }\n.own-lamborghini .hero-cta { display: flex; flex-wrap: wrap; gap: 16px; }\n.own-lamborghini .hero-controls { position: absolute; right: var(--gut); bottom: 40px; z-index: 2; }\n.own-lamborghini .hex-pause { display: grid; place-items: center; width: 52px; height: 52px; background: none; border: 1.5px solid rgba(255,255,255,.7); color: var(--white); cursor: pointer; clip-path: polygon(25% 5%, 75% 5%, 100% 50%, 75% 95%, 25% 95%, 0 50%); }\n.own-lamborghini .hex-pause svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }\n.own-lamborghini .hero-progress { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: rgba(255,255,255,.14); }\n.own-lamborghini .hero-progress i { display: block; height: 100%; width: 38%; background: var(--white); animation: lambo-progress 9s linear infinite; }\n@keyframes lambo-progress { from { width: 0; } to { width: 100%; } }\n\n/* ── sections ────────────────────────────────────────────────────────── */\n.own-lamborghini .section { padding: clamp(56px, 8cqi, 96px) 0; }\n.own-lamborghini .section.tight { padding-top: clamp(32px, 5cqi, 56px); }\n.own-lamborghini .sec-head { margin-bottom: clamp(32px, 5cqi, 56px); }\n.own-lamborghini .light { background: var(--smoke); color: var(--black); }\n.own-lamborghini .light .lead { color: var(--graphite); }\n.own-lamborghini .light .eyebrow { color: var(--gold-dark); }\n\n/* ── feature row ─────────────────────────────────────────────────────── */\n.own-lamborghini .feature { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(32px, 5cqi, 72px); align-items: center; }\n.own-lamborghini .specs { list-style: none; margin: 26px 0 30px; padding: 0; display: grid; gap: 0; border-top: 1px solid var(--charcoal); }\n.own-lamborghini .specs li { display: flex; justify-content: space-between; padding: 14px 0; border-bottom: 1px solid var(--charcoal); }\n.own-lamborghini .spec-k { font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; color: var(--ash); }\n.own-lamborghini .spec-v { font-size: 15px; text-transform: uppercase; letter-spacing: 0.2px; }\n.own-lamborghini .feature-visual { background: var(--charcoal); padding: 28px; }\n.own-lamborghini .visual-head { display: flex; align-items: center; justify-content: space-between; font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; color: var(--ash); padding-bottom: 18px; border-bottom: 1px solid #313131; }\n.own-lamborghini .tag-live { color: var(--gold-text); }\n.own-lamborghini .visual-chart { height: 150px; margin: 20px 0; }\n.own-lamborghini .visual-chart svg { width: 100%; height: 100%; }\n.own-lamborghini .visual-rows { list-style: none; margin: 0; padding: 0; }\n.own-lamborghini .vr { display: flex; align-items: center; justify-content: space-between; padding: 12px 0; border-top: 1px solid #313131; font-size: 14px; }\n.own-lamborghini .vr span:first-child { color: var(--ash); text-transform: uppercase; letter-spacing: 0.2px; font-size: 12px; }\n.own-lamborghini .vr .vr-val { color: var(--white); }\n\n/* ── models (cards) ──────────────────────────────────────────────────── */\n.own-lamborghini .models { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-lamborghini .model { background: var(--charcoal); display: flex; flex-direction: column; }\n.own-lamborghini .model-photo { position: relative; height: 220px; overflow: hidden; }\n.own-lamborghini .model-photo::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.7), rgba(0,0,0,0) 60%); }\n.own-lamborghini .photo-1 { background: linear-gradient(135deg, #1b1b1b, #000 60%), radial-gradient(circle at 70% 30%, rgba(255,192,0,.22), transparent 50%); }\n.own-lamborghini .photo-2 { background: linear-gradient(135deg, #161616, #000 60%), radial-gradient(circle at 30% 70%, rgba(41,171,226,.2), transparent 50%); }\n.own-lamborghini .photo-3 { background: linear-gradient(135deg, #1b1b1b, #000 60%), radial-gradient(circle at 60% 60%, rgba(255,192,0,.16), transparent 55%); }\n.own-lamborghini .hex { position: absolute; right: 22px; bottom: 22px; width: 44px; height: 44px; border: 1.5px solid rgba(255,255,255,.55); clip-path: polygon(25% 5%, 75% 5%, 100% 50%, 75% 95%, 25% 95%, 0 50%); }\n.own-lamborghini .model-body { padding: 26px 24px 30px; display: flex; flex-direction: column; gap: 14px; flex: 1; }\n.own-lamborghini .model-body p { color: var(--ash); font-size: 16px; line-height: 1.5; flex: 1; }\n\n/* ── stats ───────────────────────────────────────────────────────────── */\n.own-lamborghini .stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-lamborghini .stat { padding: 24px 0; border-top: 2px solid var(--black); }\n.own-lamborghini .light .stat { border-top-color: var(--gold); }\n.own-lamborghini .stat b { display: block; font-size: clamp(40px, 5cqi, 64px); font-weight: 400; line-height: 1; text-transform: uppercase; }\n.own-lamborghini .stat span { display: block; margin-top: 10px; font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; color: var(--graphite); }\n.own-lamborghini .light .stat b { color: var(--black); }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-lamborghini .tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: stretch; }\n.own-lamborghini .tier { position: relative; display: flex; flex-direction: column; padding: 28px 24px; background: var(--charcoal); border-top: 2px solid #313131; }\n.own-lamborghini .tier-feat { border-top-color: var(--gold); background: #262626; }\n.own-lamborghini .tier-flag { font-size: 11px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--gold-text); margin-bottom: 14px; }\n.own-lamborghini .tier-note { color: var(--ash); font-size: 16px; min-height: 44px; }\n.own-lamborghini .price { margin: 20px 0; }\n.own-lamborghini .price span { font-size: 44px; font-weight: 400; line-height: 1; }\n.own-lamborghini .tier-feat .price span { color: var(--gold); }\n.own-lamborghini .price small { display: block; margin-top: 6px; color: var(--ash); font-size: 13px; }\n.own-lamborghini .tier ul { list-style: none; margin: 0 0 26px; padding: 0; display: grid; gap: 12px; flex: 1; }\n.own-lamborghini .tier li { position: relative; padding-left: 24px; font-size: 15px; color: #d8d8d8; }\n.own-lamborghini .tier li::before { content: ''; position: absolute; left: 0; top: 4px; width: 16px; height: 8px; border-left: 2px solid var(--gold); border-bottom: 2px solid var(--gold); transform: rotate(-45deg); }\n\n/* ── news ────────────────────────────────────────────────────────────── */\n.own-lamborghini .news { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-lamborghini .news-card { display: flex; flex-direction: column; gap: 14px; padding: 28px 24px; background: var(--charcoal); border-top: 2px solid #313131; transition: border-color .2s; }\n.own-lamborghini .news-card:hover { border-top-color: var(--gold); }\n.own-lamborghini .news-date { font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; color: var(--ash); }\n.own-lamborghini .news-title { font-size: 27px; font-weight: 400; line-height: 1.37; text-transform: uppercase; margin: 0; }\n.own-lamborghini .news-card p { color: var(--ash); font-size: 16px; line-height: 1.5; flex: 1; }\n\n/* ── cta ─────────────────────────────────────────────────────────────── */\n.own-lamborghini .cta { display: grid; gap: 22px; justify-items: center; text-align: center; padding: clamp(48px, 7cqi, 88px) var(--gut); background: var(--charcoal); border-top: 2px solid var(--gold); }\n.own-lamborghini .cta .display-2 { margin: 0; }\n.own-lamborghini .cta p { color: var(--ash); max-width: 48ch; font-size: 18px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-lamborghini .foot { background: var(--dark-iron); padding: clamp(48px, 6cqi, 64px) 0 32px; }\n.own-lamborghini .foot-in { display: grid; grid-template-columns: 1.2fr 2.6fr; gap: 40px; }\n.own-lamborghini .foot-brand .brand-name { font-size: 18px; letter-spacing: 2px; text-transform: uppercase; }\n.own-lamborghini .foot-brand p { color: var(--ash); font-size: 14px; margin-top: 14px; max-width: 30ch; }\n.own-lamborghini .foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-lamborghini .foot-cols h4 { font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; color: var(--white); margin: 0 0 14px; font-weight: 400; }\n.own-lamborghini .foot-cols a { display: block; font-size: 14px; color: var(--ash); padding: 5px 0; transition: color .15s; }\n.own-lamborghini .foot-cols a:hover { color: var(--gold); }\n.own-lamborghini .foot-base { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 22px; border-top: 1px solid #202020; font-size: 10px; letter-spacing: 0.225px; text-transform: uppercase; color: var(--steel); }\n\n/* ── reveal ──────────────────────────────────────────────────────────── */\n.own-lamborghini .reveal { opacity: 0; transform: translateY(22px); transition: opacity .7s ease, transform .7s ease; }\n.own-lamborghini .reveal.in { opacity: 1; transform: none; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-lamborghini .feature { grid-template-columns: 1fr; }\n  .own-lamborghini .models, .own-lamborghini .news { grid-template-columns: repeat(2, 1fr); }\n  .own-lamborghini .stats { grid-template-columns: repeat(2, 1fr); }\n  .own-lamborghini .tiers { grid-template-columns: 1fr; }\n  .own-lamborghini .foot-in { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-lamborghini .display-2 { font-size: clamp(30px, 9cqi, 54px); }\n  .own-lamborghini .models, .own-lamborghini .news { grid-template-columns: 1fr; }\n  .own-lamborghini .foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-lamborghini .hero-cta { flex-direction: column; align-items: stretch; }\n  .own-lamborghini .hero-cta .btn { width: 100%; }\n  .own-lamborghini .stats { grid-template-columns: 1fr; }\n  .own-lamborghini .foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-lamborghini *, .own-lamborghini *::before, .own-lamborghini *::after {\n    animation-duration: .001ms !important; animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n  .own-lamborghini .reveal { opacity: 1; transform: none; }\n  .own-lamborghini .hero-progress i { animation: none; width: 38%; }\n}\n"};
/* ══ LAMBORGHINI — behaviour for the Northwind own layout ═══════════════════
   Renders the console rows, wires the menu drawer, count-ups, sticky nav and
   reveals. The hero is a static black stage with a decorative progress line. */

(function () {
  window.OWN_LAYOUTS = window.OWN_LAYOUTS || {};

  var ROWS = [
    { name: 'Shipments', val: '48,200' },
    { name: 'Revenue cleared', val: '$4.9M' },
    { name: 'Exceptions', val: '38' },
    { name: 'On-time', val: '96%' }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  window.OWN_LAYOUTS['lamborghini'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var rafs = [];
      var observers = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      /* ── console rows ──────────────────────────────────────────────── */
      var rows = $('#lamboRows');
      if (rows) {
        rows.innerHTML = ROWS.map(function (r) {
          return '<li class="vr"><span>' + esc(r.name) + '</span><span class="vr-val">' + esc(r.val) + '</span></li>';
        }).join('');
      }

      /* ── menu drawer ───────────────────────────────────────────────── */
      var menu = $('[data-menu]');
      var drawer = $('[data-drawer]');
      on(menu, 'click', function () {
        if (!drawer) return;
        var next = drawer.hidden;
        drawer.hidden = !next;
        menu.setAttribute('aria-expanded', String(next));
      });

      /* ── count-up ──────────────────────────────────────────────────── */
      function countTo(el, to, ms, suffix) {
        var dec = Number(el.dataset.decimals != null ? el.dataset.decimals : (to % 1 !== 0 ? 1 : 0));
        function fmt(v) { return v.toLocaleString('en-US', { minimumFractionDigits: dec, maximumFractionDigits: dec }) + suffix; }
        if (reduced) { el.textContent = fmt(to); return; }
        var from = 0, t0 = null;
        function step(t) {
          if (disposed) return;
          if (t0 === null) t0 = t;
          var k = Math.min(1, (t - t0) / ms), e = 1 - Math.pow(1 - k, 4);
          el.textContent = fmt(from + (to - from) * e);
          if (k < 1) raf(step);
        }
        raf(step);
      }

      /* ── reveals ───────────────────────────────────────────────────── */
      var io = null;
      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) {
              en.target.classList.add('in');
              if (en.target.dataset.count) countTo(en.target, Number(en.target.dataset.count), 1100, en.target.dataset.suffix || '');
              io.unobserve(en.target);
            }
          });
        }, { rootMargin: '0px 0px -8% 0px', threshold: 0.12 });
        observers.push(io);
      }
      $$('[data-reveal]').forEach(function (el) { if (io) io.observe(el); else el.classList.add('in'); });
      $$('[data-count]').forEach(function (el) {
        if (io) io.observe(el);
        else el.textContent = Number(el.dataset.count).toLocaleString('en-US') + (el.dataset.suffix || '');
      });

      /* ── sticky nav ────────────────────────────────────────────────── */
      var nav = $('#lamboNav');
      function onScroll() {
        if (disposed || !nav) return;
        nav.classList.toggle('is-stuck', root.getBoundingClientRect().top < -8);
      }
      on(window, 'scroll', onScroll, { passive: true });
      onScroll();

      /* ── smooth scroll ─────────────────────────────────────────────── */
      $$('a[href^="#"]').forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
          if (drawer && !drawer.hidden) { drawer.hidden = true; menu.setAttribute('aria-expanded', 'false'); }
        });
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
